head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDisabled]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 disabled 상태를 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 disabled 상태를 설정할 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다. (Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.)",
        "colInfo(필수) 파라미터로 disabled 상태를 설정할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다. (Column 의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.)",
        "disabled 파라미터를 true 로 설정 시 Body Cell 을 disabled 상태로 설정해야 합니다.",
        "disabled 파라미터를 false 로 설정 시 Body Cell 의 disabled 상태를 해제해야 합니다.",
        "disabled 파라미터를 '' 로 설정 시 Body Cell 의 disabled 상태를 해제하며 false 가 설정되어야 합니다.",
        "disabled(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "특정 Body Cell 한 개의 disabled 상태를 설정하며 다른 Row 의 동일 위치 Body Cell 은 변경되지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="setCellDisabled 로 특정 Body Cell 의 disabled 를 true / false / 빈문자열 / 생략 설정 후 getCellDisabled 로 결과 확인 / Column 1 → 숨김 (숨겨진 Column 도 인덱스 포함)"', '', 'label1');

    // 조건 설정 (disabled Cell 을 배경색으로 구분: disabled=회색)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 두번째 컬럼 숨김 (숨겨진 Column 도 인덱스에 포함됨을 검증)
    target1.setColumnVisible(1, false);
}



scwin.btn_setCellDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = Number(par_colInfo.getText());
    let disabledText = par_disabled.getValue();

    if (disabledText === 'omit') {
        // 파라미터 생략 → 기본값 false
        target1.setCellDisabled(rowIndex, colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("setCellDisabled(" + rowIndex + ", " + colInfo + ")");
    } else if (disabledText === '') {
        // 빈 문자열 설정 → 상위 모듈 disabled 적용
        target1.setCellDisabled(rowIndex, colInfo, "");
        wf_body_bottom.getObj("scwin").setReturnValue("setCellDisabled(" + rowIndex + ", " + colInfo + ", '')");
    } else {
        let disabled = disabledText === 'true';
        target1.setCellDisabled(rowIndex, colInfo, disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("setCellDisabled(" + rowIndex + ", " + colInfo + ", " + disabled + ")");
    }

    scwin.btn_getCellDisabled_onclick();
}



scwin.btn_getCellDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = Number(par_colInfo.getText());

    // Cell 단위 disabled 상태 (getCellDisabled)
    let cellRtn = target1.getCellDisabled(rowIndex, colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellDisabled(" + rowIndex + ", " + colInfo + ") : " + cellRtn);
}
